import{X as e,Z as t,t as n,ut as r}from"./chunks/framework.Cq50P25D.js";var i=JSON.parse(`{"title":"Runtime Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"usage/permissions.md","filePath":"en/usage/permissions.md","lastUpdated":1787300168000}`),a={name:`usage/permissions.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="runtime-permissions" tabindex="-1">Runtime Permissions <a class="header-anchor" href="#runtime-permissions" aria-label="Permalink to “Runtime Permissions”">​</a></h1><p>This page is an exhaustive list of runtime APIs used by Sync Engine and official modules that may raise concerns, with verifiable explanations that justify their necessity. You can also compare this list against Obsidian Community website &quot;Disclosure&quot; section in the plugin scorecard.</p><h2 id="dynamic-javascript-module-evaluation" tabindex="-1">Dynamic JavaScript Module Evaluation <a class="header-anchor" href="#dynamic-javascript-module-evaluation" aria-label="Permalink to “Dynamic JavaScript Module Evaluation”">​</a></h2><p>Dynamic JavaScript module evaluation is a type of <em>dynamic code execution</em>, which is similar to how Obsidian loads plugins. It is essential for Sync Engine&#39;s extensible architecture.</p><p>Sync Engine only evaluates JavaScript ESM modules explicitly downloaded or approved by the user, and only when the plugin starts, a module auto-updates, or the user explicitly toggles.</p><p>Sync Engine implements a series of mechanisms to minimize the attack surface brought by module evaluation. Refer to <a href="./security">Security</a> for more detail.</p><h2 id="access-and-modify-vault-files" tabindex="-1">Access and Modify Vault Files <a class="header-anchor" href="#access-and-modify-vault-files" aria-label="Permalink to “Access and Modify Vault Files”">​</a></h2><p>Sync Engine accesses and modifies vault files for basic syncing and module management requirements.</p><p>It obtains the last modified time and file size for each file to detect changes; reads files and uploads to configured syncing backend; and updates or deletes local files according to detected remote changes. Deleted files follow Obsidian&#39;s trash setting and can go to system trash, the vault trash folder, or be permanently deleted.</p><p>Sync Engine only accesses and modifies vault files during sync runs, and it never tries to access files that are explicitly excluded by <a href="./settings#inclusion-and-exclusion-rules">inclusion and exclusion rules</a>.</p><p>Sync Engine also persists its modules in <code>&lt;vault folder&gt;/.obsidian/plugins/sync-engine/modules/</code>.</p><h2 id="network-requests" tabindex="-1">Network Requests <a class="header-anchor" href="#network-requests" aria-label="Permalink to “Network Requests”">​</a></h2><p>Sync Engine only makes network requests for the two purposes below:</p><ul><li>performs authorization and syncs files to the configured backend</li><li>fetches module sources and downloads modules</li></ul><p>Requests made for syncing purpose only happen during sync runs.</p><p>Module sources are fetched only when automatic module update starts or user opens the module management page. Sync Engine only fetches module sources defined in the &quot;Module sources&quot; setting. Modules are only downloaded when the user manually downloads a module or during module auto update.</p><p>The only default module source is <code>https://sync.consensia.cc/modules.json</code>, <code>sync.consensia.cc</code> is hosted on GitHub pages, whose source code is 100% transparent and verifiable in Sync Engine GitHub repository.</p><p>Sync Engine plugin and <code>sync.consensia.cc</code> don&#39;t contain any type of telemetry.</p><h2 id="obsidian-secret-storage" tabindex="-1">Obsidian Secret Storage <a class="header-anchor" href="#obsidian-secret-storage" aria-label="Permalink to “Obsidian Secret Storage”">​</a></h2><p>Obsidian secret storage is shown as &quot;Keychain&quot; in Obsidian settings. Sync Engine and official modules acquire secrets in following scenarios:</p><ul><li>Plugin core: reads the configured <a href="./settings#custom-headers">secret headers</a> at the start of a sync run</li><li><a href="./../deep-dive/modules/webdav">WebDAV</a> module: reads the configured WebDAV token secret at the start of a sync run for service authentication</li><li><a href="./../deep-dive/modules/s3">S3</a> module: reads the configured secret access key when resolving S3 credentials for connection checks or sync operations</li><li><a href="./../deep-dive/modules/encryption">Encryption</a> module: reads the configured encryption password secret at the start of a sync run for later encryption and decryption</li></ul><p>Sync Engine and official modules never read beyond what is provided by the user.</p><h2 id="indexeddb-storage" tabindex="-1">IndexedDB Storage <a class="header-anchor" href="#indexeddb-storage" aria-label="Permalink to “IndexedDB Storage”">​</a></h2><p>IndexedDB is a browser API to store data in an embedded database instead of physical files. Sync Engine utilizes IndexedDB through the <a href="https://github.com/hesprs/uni-kv" target="_blank" rel="noreferrer"><code>uni-kv</code></a> package.</p><p>The plugin core uses IndexedDB for following purposes:</p><ul><li>records the unique identifiers of known synced local and remote files, to facilitate the three-way change detection of next sync</li><li>records metadata including enable state and integrity hash for each installed module. This is because IndexedDB is immune from common vault file replacement attacks, Sync Engine utilizes this to guard module execution to the only ones approved by the user</li></ul>`,26)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};